class Solution:
    def xorOperation(self, n: int, start: int) -> int:
        ans = 0
        for i in range(n):
            ans ^= (start + 2 * i)
        return ans

class Solution {
public:
    int xorOperation(int n, int start) {
        int ans = 0;
        for (int i = 0; i < n; ++i) {
            ans ^= (start + 2 * i);
        }
        return ans;
    }
};

class Solution {
    public int xorOperation(int n, int start) {
        int ans = 0;
        for (int i = 0; i < n; i++) {
            ans ^= (start + 2 * i);
        }
        return ans;
    }
}

var xorOperation = function(n, start) {
    let ans = 0;
    for (let i = 0; i < n; i++) {
        ans ^= (start + 2 * i);
    }
    return ans;
};
